import{_ as s,C as r,o as n,c as i,ag as t,E as a}from"./chunks/framework.D1z9wg1y.js";const w=JSON.parse('{"title":"Agents and their roles","description":"","frontmatter":{},"headers":[],"relativePath":"agentic/agents.md","filePath":"agentic/agents.md"}'),d={name:"agentic/agents.md"};function l(h,e,c,u,p,f){const o=r("CallGraph");return n(),i("div",null,[e[0]||(e[0]=t('<h1 id="agents-and-their-roles" tabindex="-1">Agents and their roles <a class="header-anchor" href="#agents-and-their-roles" aria-label="Permalink to &quot;Agents and their roles&quot;">​</a></h1><p>One session of a <a href="./../concepts#coding-agent">coding agent</a> can write a change, run its tests and review it. It does all three badly at once: its context fills with test output, and it judges its own code too kindly. The harness therefore gives each kind of work to an agent of its own. This page names the roles, says why each one is separate, and shows which agent starts which. <a href="./loop">The builder-critic loop</a> shows the roles at work on one change.</p><h2 id="sub-agents" tabindex="-1">Sub-agents <a class="header-anchor" href="#sub-agents" aria-label="Permalink to &quot;Sub-agents&quot;">​</a></h2><p>A session can start a <a href="./../concepts#sub-agent">sub-agent</a> for one job. The sub-agent works in a context of its own and returns one short report, so the output of its job never fills the context of the session. The harness gives sub-agents three kinds of jobs:</p><ul><li><strong>A long job</strong>, such as a test suite: <a href="./../components/agents#julia-test-runner"><code>julia-test-runner</code></a> runs it and returns pass or fail per testset, with the failures.</li><li><strong>A wide job</strong>, such as a change across many repositories: one sub-agent for each repository, and one verdict for each.</li><li><strong>A bounded diagnosis</strong>, such as a package that does not load: <a href="./../components/agents#julia-load-doctor"><code>julia-load-doctor</code></a> returns the cause and the smallest fix.</li></ul><p>A sub-agent costs a new context, so a session starts one only where a fresh context or a smaller model does the work better. <a href="./../components/agents#reader"><code>reader</code></a> and <a href="./../components/agents#worker"><code>worker</code></a> load no <code>CLAUDE.md</code>, so they start with a small context. A reader changes nothing; a worker does one fully specified change.</p><h2 id="the-roles" tabindex="-1">The roles <a class="header-anchor" href="#the-roles" aria-label="Permalink to &quot;The roles&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">role</th><th style="text-align:left;">agents</th><th style="text-align:left;">what it does</th><th style="text-align:left;">why it is separate</th></tr></thead><tbody><tr><td style="text-align:left;">planner</td><td style="text-align:left;">your session, with the skill <a href="./../components/skills#plan-parts"><code>plan-parts</code></a></td><td style="text-align:left;">splits a task into parts and writes the spec of each part</td><td style="text-align:left;">the plan is the user&#39;s decision; a builder does not choose its own goal</td></tr><tr><td style="text-align:left;">builder</td><td style="text-align:left;"><code>julia-builder</code>, <code>python-builder</code>, <code>part-builder</code></td><td style="text-align:left;">writes the tests, then the code, in a worktree; runs the gate</td><td style="text-align:left;">it holds the design in its context</td></tr><tr><td style="text-align:left;">critic</td><td style="text-align:left;"><code>julia-critic</code>, <code>python-critic</code>, <code>part-critic</code></td><td style="text-align:left;">judges the branch against the spec, blind</td><td style="text-align:left;">a context that wrote the code does not judge it well</td></tr><tr><td style="text-align:left;">advisor</td><td style="text-align:left;"><code>advisor</code></td><td style="text-align:left;">decides one question inside the loop, in place of the user</td><td style="text-align:left;">the builder stops less often, and the critic stays blind</td></tr><tr><td style="text-align:left;">arbitrator</td><td style="text-align:left;"><code>arbitrator</code></td><td style="text-align:left;">rules on a loop that does not converge</td><td style="text-align:left;">a third round of the same approach seldom closes</td></tr><tr><td style="text-align:left;">test runner</td><td style="text-align:left;"><code>julia-test-runner</code></td><td style="text-align:left;">runs a long suite and returns the verdict</td><td style="text-align:left;">the large contexts do not wait on a slow suite</td></tr><tr><td style="text-align:left;">verifier</td><td style="text-align:left;"><code>julia-branch-verifier</code></td><td style="text-align:left;">checks and fixes the diff of a branch before its pull request</td><td style="text-align:left;">a fixed list of checks, on the diff only</td></tr><tr><td style="text-align:left;">reviewer</td><td style="text-align:left;"><code>julia-pr-reviewer</code></td><td style="text-align:left;">reviews a pull request and posts the review</td><td style="text-align:left;">the review comes from a context that has not decided how to fix anything</td></tr><tr><td style="text-align:left;">shepherd</td><td style="text-align:left;"><code>julia-pr-shepherd</code></td><td style="text-align:left;">has the review done, fixes the findings and pushes</td><td style="text-align:left;">it takes a pull request from review to green CI</td></tr><tr><td style="text-align:left;">specialists</td><td style="text-align:left;"><code>julia-load-doctor</code>, <code>julia-perf-analyst</code>, <code>ci-triage</code>, <code>changelog-scribe</code>, <code>exhaustive-auditor</code>, <code>literature-scout</code>, <code>latex-verifier</code>, <code>editor</code>, <code>writer</code></td><td style="text-align:left;">one bounded kind of work each</td><td style="text-align:left;">each returns a short, fixed verdict</td></tr></tbody></table><p><a href="./../components/agents">Agents</a> describes each agent: its tools, its model and its report.</p><p><strong>The builder and the critic never share a context.</strong> The critic gets the spec, the branch and the base, and never the builder&#39;s report or reasoning. A FAIL goes to a new builder, and the next round to a new critic. So each judgement comes from a context that has no stake in the code.</p><p><strong>A question goes to an agent, not to you, while the loop runs.</strong> The advisor decides a question that the spec leaves open, and says how sure it is. When the decision is not reversible inside the pull request, the loop parks the part and asks you. The arbitrator reads the whole loop and picks one move from a fixed list, such as a redesign or a fresh build. Both edit nothing.</p><h2 id="models-and-efforts" tabindex="-1">Models and efforts <a class="header-anchor" href="#models-and-efforts" aria-label="Permalink to &quot;Models and efforts&quot;">​</a></h2><p>An agent names a <a href="./../concepts#tier">tier</a>: <code>large</code>, <code>medium</code> or <code>small</code>. The model tables of the <a href="./../concepts#profile">profile</a> give the model of each tier for each frontend. A builder and a critic need a large model; a test run needs only a medium one, so the large contexts do not wait on it. An agent can also name an <a href="./../concepts#effort">effort</a>. The figures below show the model and the effort of each agent.</p><h2 id="who-spawns-whom" tabindex="-1">Who spawns whom <a class="header-anchor" href="#who-spawns-whom" aria-label="Permalink to &quot;Who spawns whom&quot;">​</a></h2><p>An agent can start another agent. This page calls this a <em>spawn</em>: the first agent gives a task to a new agent, the new agent works in a context of its own, and it returns one report. Some skills spawn agents too. A skill runs in the session that loads it, so the session does the spawn.</p><p>Each figure below is a call graph: a box is an agent or a skill, and an arrow goes from the caller to the agent that it spawns. The text on an arrow says when or why the caller spawns the agent.</p><h3 id="how-to-read-a-figure" tabindex="-1">How to read a figure <a class="header-anchor" href="#how-to-read-a-figure" aria-label="Permalink to &quot;How to read a figure&quot;">​</a></h3><p>Each box shows three facts:</p><ul><li><strong>The name</strong>, in bold. A blue box is an agent of <code>agents/</code>. A yellow box is a skill of <code>skills/</code>.</li><li><strong>The model.</strong> The source names a model tier, <code>large</code>, <code>medium</code> or <code>small</code>, and the <code>[claude]</code> table of <code>examples/models.toml</code> gives the model of each tier: <code>opus</code>, <code>sonnet</code> and <code>haiku</code>. Your own <code>models.toml</code> changes these models (see <a href="./../profile">Adapting the profile</a>). A source with no <code>model:</code> runs on the model of its caller, and its box says &quot;the caller&#39;s model&quot;. A skill runs in the session that loads it, on the session&#39;s model, so a skill box says &quot;the session&#39;s model&quot;.</li><li><strong>The effort</strong>, from the source&#39;s <code>effort:</code>. A source with no <code>effort:</code> runs at the effort of the session, and its box says &quot;the session&#39;s effort&quot;. Where a caller sets a different effort for one spawn, the arrow says so: &quot;at high effort&quot;.</li></ul><p>The figures show Claude Code. OpenCode and oh-my-pi can run a council: copies of an agent on other models, each copy a seat. The figures do not draw the councils.</p><p>The arrows come from one file, <code>docs/figures/calls.toml</code>. It has one entry for each spawn, with the <code>file:line</code> of the instruction that spawns the agent. <code>harness test</code> checks each entry against the sources, and the docs build draws the figures from it. So a figure changes when an agent changes.</p><h3 id="the-builder-critic-loop-build-part" tabindex="-1">The builder-critic loop: <code>build-part</code> <a class="header-anchor" href="#the-builder-critic-loop-build-part" aria-label="Permalink to &quot;The builder-critic loop: `build-part`&quot;">​</a></h3>',22)),a(o,{root:"build-part",title:"The calls of build-part",desc:"The build-part skill spawns julia-builder or python-builder, julia-critic or python-critic in round 1 at high effort and in each verify round at its own effort, julia-test-runner, advisor and arbitrator. julia-builder spawns julia-branch-verifier and changelog-scribe."}),e[1]||(e[1]=t('<p>You start <code>build-part</code> in your session when a part is ready to build. The skill does not write code. It spawns a builder to build the part, and then new critics to judge the result: <code>julia-builder</code> and <code>julia-critic</code> for a Julia part, <code>python-builder</code> and <code>python-critic</code> for a Python part, and <code>part-builder</code> and <code>part-critic</code> in a repository with neither a <code>Project.toml</code> nor a <code>pyproject.toml</code>. Beside each critic, <code>julia-test-runner</code> runs the full test suite of a Julia part; for any other part the skill&#39;s session runs the repository&#39;s own suite in the background. A question inside the loop goes to the <code>advisor</code>, and a loop that does not converge goes to the <code>arbitrator</code>. Before the pull request of a Julia part, <code>julia-builder</code> spawns <code>julia-branch-verifier</code>, and it can spawn <code>changelog-scribe</code> for a fix of the CHANGELOG. <a href="./loop#the-full-loop-build-part">The builder-critic loop</a> follows one part through it.</p><h3 id="a-smaller-loop-build-reviewed" tabindex="-1">A smaller loop: <code>build-reviewed</code> <a class="header-anchor" href="#a-smaller-loop-build-reviewed" aria-label="Permalink to &quot;A smaller loop: `build-reviewed`&quot;">​</a></h3>',2)),a(o,{root:"build-reviewed",title:"The calls of build-reviewed",desc:"The build-reviewed skill spawns part-builder, part-critic and julia-test-runner. part-builder spawns julia-branch-verifier."}),e[2]||(e[2]=t('<p>A part of tier <code>reviewed</code> is small, with a fast gate. The skill spawns one <code>part-builder</code>, and a new one for each later round, and one <code>part-critic</code>, which judges the work once. A run longer than five minutes goes to <code>julia-test-runner</code>. Before the pull request, the builder spawns <code>julia-branch-verifier</code>. <a href="./loop#the-small-loop-build-reviewed">The builder-critic loop</a> follows one part through it.</p><h3 id="from-review-to-green-ci-julia-pr-shepherd" tabindex="-1">From review to green CI: <code>julia-pr-shepherd</code> <a class="header-anchor" href="#from-review-to-green-ci-julia-pr-shepherd" aria-label="Permalink to &quot;From review to green CI: `julia-pr-shepherd`&quot;">​</a></h3>',2)),a(o,{root:"julia-pr-shepherd",title:"The calls of julia-pr-shepherd",desc:"The julia-pr-shepherd agent spawns julia-pr-reviewer, changelog-scribe and ci-triage."}),e[3]||(e[3]=t('<p>You spawn <code>julia-pr-shepherd</code> with a pull request of a Julia package. It does not review the pull request itself: it spawns <code>julia-pr-reviewer</code>, which posts the review. Then the shepherd fixes the findings. When the fix changes behaviour, it spawns <code>changelog-scribe</code> for the CHANGELOG entry. When CI is red in several jobs, it spawns <code>ci-triage</code> to separate the real failures from the known ones. <a href="./review">Review and pull requests</a> describes the three agents of a pull request.</p><h3 id="every-spawn" tabindex="-1">Every spawn <a class="header-anchor" href="#every-spawn" aria-label="Permalink to &quot;Every spawn&quot;">​</a></h3>',2)),a(o,{title:"Every spawn",desc:"Every edge of calls.toml: the build-part, build-reviewed, plan-parts and julia-structure skills, and the julia-builder, part-builder, julia-pr-shepherd and editor agents, with each agent that they spawn."}),e[4]||(e[4]=t("<p>This figure shows every entry of <code>calls.toml</code>. It adds two skills: <code>plan-parts</code> sends each part&#39;s spec to a <code>reader</code> that measures its facts, and <code>julia-structure</code> sends a claim that nothing uses a name to <code>exhaustive-auditor</code>. An agent that is not in this figure is spawned only from your session. Only the agents with the tool <code>agent</code> can spawn another agent: <code>julia-builder</code>, <code>part-builder</code>, <code>julia-pr-shepherd</code> and <code>editor</code>. Each spawn costs a new context, so an agent spawns another only where a fresh context or a smaller model does the work better.</p>",1))])}const b=s(d,[["render",l]]);export{w as __pageData,b as default};
